enhanced_schema:
{
  "tables": [
    {
      "table_name": "market_data",
      "columns": [
        {
          "name": "data_id",
          "type": "INTEGER",
          "description": "Unique identifier for each market data entry"
        },
        {
          "name": "datetime",
          "type": "DATETIME",
          "description": "Timestamp of the market data entry"
        },
        {
          "name": "instrument_id",
          "type": "INTEGER",
          "description": "Identifier for the financial instrument"
        },
        {
          "name": "open",
          "type": "FLOAT",
          "description": "Opening price of the instrument at the given timestamp"
        },
        {
          "name": "high",
          "type": "FLOAT",
          "description": "Highest price of the instrument at the given timestamp"
        },
        {
          "name": "low",
          "type": "FLOAT",
          "description": "Lowest price of the instrument at the given timestamp"
        },
        {
          "name": "close",
          "type": "FLOAT",
          "description": "Closing price of the instrument at the given timestamp"
        },
        {
          "name": "volume",
          "type": "FLOAT",
          "description": "Trading volume for the instrument"
        },
        {
          "name": "adjusted_close",
          "type": "FLOAT",
          "description": "Adjusted closing price for corporate actions"
        },
        {
          "name": "currency",
          "type": "VARCHAR",
          "description": "Currency in which the instrument is traded"
        }
      ],
      "primary_key": [
        "data_id"
      ]
    },
    {
      "table_name": "financial_instruments",
      "columns": [
        {
          "name": "instrument_id",
          "type": "INTEGER",
          "description": "Unique identifier for each financial instrument"
        },
        {
          "name": "instrument_name",
          "type": "VARCHAR",
          "description": "Name of the financial instrument"
        },
        {
          "name": "instrument_type",
          "type": "VARCHAR",
          "description": "Type of the financial instrument (e.g., stock, bond, forex)"
        },
        {
          "name": "market",
          "type": "VARCHAR",
          "description": "Market where the instrument is traded"
        },
        {
          "name": "sector",
          "type": "VARCHAR",
          "description": "Industry sector of the instrument"
        },
        {
          "name": "country",
          "type": "VARCHAR",
          "description": "Country where the instrument is issued or primarily traded"
        },
        {
          "name": "exchange",
          "type": "VARCHAR",
          "description": "Exchange where the instrument is listed"
        }
      ],
      "primary_key": [
        "instrument_id"
      ]
    },
    {
      "table_name": "users",
      "columns": [
        {
          "name": "user_id",
          "type": "INTEGER",
          "description": "Unique identifier for each user"
        },
        {
          "name": "user_name",
          "type": "VARCHAR",
          "description": "Full name of the user"
        },
        {
          "name": "email",
          "type": "VARCHAR",
          "description": "Email address of the user"
        },
        {
          "name": "role",
          "type": "VARCHAR",
          "description": "Role of the user (e.g., trader, analyst, admin)"
        },
        {
          "name": "last_login",
          "type": "DATETIME",
          "description": "Timestamp of the user's last login"
        },
        {
          "name": "status",
          "type": "VARCHAR",
          "description": "Account status (e.g., active, inactive, suspended)"
        },
        {
          "name": "department",
          "type": "VARCHAR",
          "description": "Department the user belongs to"
        }
      ],
      "primary_key": [
        "user_id"
      ]
    },
    {
      "table_name": "access_logs",
      "columns": [
        {
          "name": "access_id",
          "type": "INTEGER",
          "description": "Unique identifier for each access event"
        },
        {
          "name": "data_id",
          "type": "INTEGER",
          "description": "ID of the market data being accessed"
        },
        {
          "name": "user_id",
          "type": "INTEGER",
          "description": "ID of the user accessing the data"
        },
        {
          "name": "access_date",
          "type": "DATE",
          "description": "Date when the data was accessed"
        },
        {
          "name": "access_type",
          "type": "VARCHAR",
          "description": "Type of access (e.g., view, download)"
        },
        {
          "name": "ip_address",
          "type": "VARCHAR",
          "description": "IP address of the user during access"
        },
        {
          "name": "device",
          "type": "VARCHAR",
          "description": "Device type used to access the platform"
        }
      ],
      "primary_key": [
        "access_id"
      ]
    },
    {
      "table_name": "analytics",
      "columns": [
        {
          "name": "analysis_id",
          "type": "INTEGER",
          "description": "Unique identifier for each analysis result"
        },
        {
          "name": "instrument_id",
          "type": "INTEGER",
          "description": "ID of the financial instrument analyzed"
        },
        {
          "name": "analysis_date",
          "type": "DATE",
          "description": "Date when the analysis was conducted"
        },
        {
          "name": "result_summary",
          "type": "TEXT",
          "description": "Summary of the analysis results"
        },
        {
          "name": "model_used",
          "type": "VARCHAR",
          "description": "Model or method used for the analysis"
        },
        {
          "name": "confidence_level",
          "type": "FLOAT",
          "description": "Confidence level of the predictive model"
        },
        {
          "name": "parameters",
          "type": "JSON",
          "description": "Parameters used in analysis models"
        }
      ],
      "primary_key": [
        "analysis_id"
      ]
    },
    {
      "table_name": "trading_strategies",
      "columns": [
        {
          "name": "strategy_id",
          "type": "INTEGER",
          "description": "Unique identifier for each trading strategy"
        },
        {
          "name": "user_id",
          "type": "INTEGER",
          "description": "ID of the user who created the strategy"
        },
        {
          "name": "strategy_name",
          "type": "VARCHAR",
          "description": "Name of the trading strategy"
        },
        {
          "name": "description",
          "type": "TEXT",
          "description": "Description of the trading strategy"
        },
        {
          "name": "created_date",
          "type": "DATE",
          "description": "Date when the strategy was created"
        },
        {
          "name": "last_run_date",
          "type": "DATETIME",
          "description": "The last date the strategy was executed"
        },
        {
          "name": "performance_metrics",
          "type": "JSON",
          "description": "Performance metrics of the strategy"
        },
        {
          "name": "is_active",
          "type": "BOOLEAN",
          "description": "Indicates whether the strategy is currently active"
        }
      ],
      "primary_key": [
        "strategy_id"
      ]
    }
  ],
  "foreign_keys": [
